from collections import defaultdict


def main():
    data = sys.stdin.buffer
    first = data.readline().split()
    if not first:
        return
    n, q = map(int, first)

    # Segment tree over operation times, with edges active on half-open intervals.
    tree = [[] for _ in range(4 * q)]

    def add_interval(node, left, right, ql, qr, edge):
        if ql >= right or qr <= left:
            return
        if ql <= left and right <= qr:
            tree[node].append(edge)
            return
        mid = (left + right) // 2
        add_interval(node * 2, left, mid, ql, qr, edge)
        add_interval(node * 2 + 1, mid, right, ql, qr, edge)

    counts = defaultdict(int)
    starts = {}
    operations = []

    for t in range(q):
        parts = data.readline().split()
        op = parts[0].decode()
        u = int(parts[1]) - 1
        v = int(parts[2]) - 1 if op != '?' else -1
        operations.append((op, u))

        if op == '+':
            a, b = (u, v) if u <= v else (v, u)
            key = (a, b)
            if counts[key] == 0:
                starts[key] = t
            counts[key] += 1
        elif op == '-':
            a, b = (u, v) if u <= v else (v, u)
            key = (a, b)
            if counts[key] > 0:
                counts[key] -= 1
                if counts[key] == 0:
                    begin = starts.pop(key)
                    if begin < t:
                        add_interval(1, 0, q, begin, t, key)

    for key, begin in starts.items():
        if begin < q:
            add_interval(1, 0, q, begin, q, key)

    parent = list(range(n))
    size = [1] * n
    history = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            history.append(None)
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        history.append((rb, ra, size[ra]))
        parent[rb] = ra
        size[ra] += size[rb]

    answers = []

    def visit(node, left, right):
        mark = len(history)
        for a, b in tree[node]:
            if a != b:
                union(a, b)
        if right - left == 1:
            op, u = operations[left]
            if op == '?':
                answers.append(str(size[find(u)]))
        else:
            mid = (left + right) // 2
            visit(node * 2, left, mid)
            visit(node * 2 + 1, mid, right)
        while len(history) > mark:
            change = history.pop()
            if change is not None:
                child, root, old_size = change
                parent[child] = child
                size[root] = old_size

    if q:
        visit(1, 0, q)
    sys.stdout.write('\n'.join(answers))
    if answers:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()
